package com.dlxyuki.wms.pickingbol;
import com.dlxyuki.wms.user.UserAccount;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/picking-lists") public class PickingBolController{private static final MediaType XLSX=MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");private final PickingBolService service;public PickingBolController(PickingBolService s){service=s;}@GetMapping List<Map<String,Object>> list(@AuthenticationPrincipal UserAccount u){return service.list(u);}@GetMapping("/{pickingId}/xlsx") ResponseEntity<byte[]> export(@PathVariable long pickingId,@AuthenticationPrincipal UserAccount u){var p=service.get(pickingId,u);return ResponseEntity.ok().contentType(XLSX).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+p.get("picking_no")+".xlsx").body(service.export(pickingId,u));}@GetMapping("/{pickingId}") Map<String,Object> get(@PathVariable long pickingId,@AuthenticationPrincipal UserAccount u){return service.get(pickingId,u);}}
